10	  "verse_id": "5.56.1",
11	  "sarga": 56,
12	  "verse": "1",
13	  "ambiguous_marker": false,
14	  "sanskrit_iast": "tatas tu śiṃśapāmūle jānakīṃ paryavasthitām । abhivādyābravīd diṣṭyā paśyāmi tvām ihākṣatām ॥1॥",
15	  "leonov_ru": "И вот под деревом ашоки стоящую Джанаки Поприветствовав, сказал [Хануман]: «К счастью вижу я тебя здесь невредимой».",
16	  "commentary": {
17	    "bhusana": "ततस्तु शिंशुपामूले जानकीं पर्यवस्थिताम् ।\n\nअभिवाद्याब्रवीद्दिष्ट्या पश्यामि त्वामिहाक्षताम्"
18	  },
19	  "pratika_check": {
20	    "bhusana": {
21	      "pratika_iast": "tatastu sinsupanule janakin paryavasthitan",
22	      "matches_verse": true
23	    }
24	  }
