875	      "verse_id": "5.57.42",
876	      "sarga": 57,
877	      "verse": "42",
878	      "ambiguous_marker": false,
879	      "sanskrit_iast": "cakruḥ kilakilām anye pratigarjanti cāpare । ke cid ucchritalāṅgūlāḥ prahṛṣṭāḥ kapikuñjarāḥ ॥42॥",
880	      "leonov_ru": "Издавали звук (радости) «кила-кила» другие, иные в ответ ревели, Некоторые обрадованные обезьяны задрали хвосты.",
881	      "commentary": {
882	        "bhusana": "केचिदुच्छ्रितलाङ्गूलाः प्रहृष्टाः कपिकुञ्जराः ।\n\nअञ्चिता यतदीर्घाणि लांगूलानि प्रविव्यधुः\nकेचिदिति । अञ्चितायतदीर्घाणि अत्र दीर्घपदसन्निधानादायतपदं स्थूलपरम् । प्रविव्यधुः लाङ्गूलान्युद्धृत्य भूमावताडयन्नित्यर्थः"
883	      },
884	      "pratika_check": {
885	        "bhusana": {
886	          "pratika_iast": "keciducchritalangulah prahrstah kapikunjarah",
887	          "matches_verse": true
888	        }
889	      }
890	    },
891	    {
892	      "verse_id": "5.57.43",
893	      "sarga": 57,
894	      "verse": "43",
895	      "ambiguous_marker": false,
896	      "sanskrit_iast": "āyatāñcitadīrghāṇi lāṅgūlāni pravivyadhuḥ । apare tu hanūmantaṃ śrīmantaṃ vānarottamam ॥43॥",
897	      "leonov_ru": "Толстые (широкие), изогнутые, длинные хвосты вздымали и опускали (били хвостами), Иные же, Ханумана мудрого, лучшего между обезьянами,",
898	      "commentary": {
899	        "tilaka": "आयताञ्चितदीर्घाणि । आयामो विस्तारः, स्थौल्यमित्यन्ये",
900	        "bhusana": "अपरे च हनूमन्तं वानरा वारणोपमम् ।\n\nआप्लुत्य गिरिशृङ्गेभ्यः संस्पृशन्ति स्म हर्षिताः\nअपरे चेति । संस्पृशन्ति आलिङ्गन्तीत्यर्थः ।। 5.57.43,44 ।।\n\nसत्त्वे वीर्ये न ते कश्चित् समो वानर विद्यते ।\n\nयदवप्लुत्य विस्तीर्णं सागरं पुनरागतः",
901	        "siromani": "अपरे इति । अपरे तु आप्लुत्य हनूमन्तं संस्पृशन्ति\nकेचिदिति । केचित् आयताञ्चितानि विस्तारं प्राप्तान्येव लाङ्गूलानि प्रविव्यधुः"
902	      },
