993	          "pratika_iast": "aho",
994	          "matches_verse": true
995	        }
996	      }
997	    },
998	    {
999	      "verse_id": "5.57.48",
1000	      "sarga": 57,
1001	      "verse": "48",
1002	      "ambiguous_marker": false,
1003	      "sanskrit_iast": "diṣṭyā dṛṣṭā tvayā devī rāmapatnī yaśasvinī । diṣṭyā tyakṣyati kākutsthaḥ śokaṃ sītāviyogajam ॥48॥",
1004	      "leonov_ru": "Хвала судьбе, нашел (увидел) ты царевну, славную жену Рамы, Хвала судьбе, оставит Какутстха скорбь, рожденную разлукой с Ситой.",
1005	      "commentary": {
1006	        "bhusana": "दिष्ट्या त्यक्ष्यति काकुत्स्थः शोकं सीतावियोगजम् ।\n\nततो ऽङ्गदं हनूमन्तं जाम्बवन्तं च वानराः",
1007	        "siromani": "दिष्ट्येति । दिष्ट्या अस्मद्भाग्योदयेन काकुत्स्थो रामः शोकं त्यक्ष्यति"
1008	      },
1009	      "pratika_check": {
