1019	    },
1020	    {
1021	      "verse_id": "5.57.49",
1022	      "sarga": 57,
1023	      "verse": "49",
1024	      "ambiguous_marker": false,
1025	      "sanskrit_iast": "tato 'ṅgadaṃ hanūmantaṃ jāmbavantaṃ ca vānarāḥ । parivārya pramuditā bhejire vipulāḥ śilāḥ ॥49॥",
1026	      "leonov_ru": "Тогда Ангаду, Ханумана и Джамбавана окружив, Обрадованные обезьяны забрались на обширные камни.",
1027	      "commentary": {
1028	        "bhusana": "परिवार्य प्रमुदिता भेजिरे विपुलाः शिलाः ।\n\nश्रोतुकामाः समुद्रस्य लङ्घनं वानरोत्तमाः"
1029	      },
1030	      "pratika_check": {
1031	        "bhusana": {
1032	          "pratika_iast": "parivarya pranudita bhejire vipulah",
1033	          "matches_verse": true
1034	        }
1035	      }
1036	    },
1037	    {
1038	      "verse_id": "5.57.50",
1039	      "sarga": 57,
1040	      "verse": "50",
1041	      "ambiguous_marker": false,
1042	      "sanskrit_iast": "upāviṣṭā gires tasya silāsu vipulāsu te । śrotukāmāḥ samudrasya laṅghanaṃ vānarottamāḥ ॥50॥",
1043	      "leonov_ru": "Забравшись на обширные камни той горы, те лучшие из обезьян, Желая услышать о пересечении океана,",
1044	      "commentary": {
1045	        "siromani": "उपविष्टा इति । गिरेः शिलासु उपविष्टाः समुद्रलङ्घनादीनि श्रोतुकामाः अत एव हनुमद्वदनोन्मुखाः सर्वे अङ्गदप्रभृतयः तस्थुः । श्लोकद्वयमेकान्वयि ।। 5.57.50,51 ।।\n\nस्थितिप्रकारं बोधयन्नाह तस्थाविति । विविधैर्देवैरुपास्यमानो देवपतिरिवाङ्गदस्तस्थौ"
1046	      },
1047	      "pratika_check": {
1048	        "siromani": {
1049	          "pratika_iast": "upavista",
1050	          "matches_verse": true
1051	        }
1052	      }
1053	    },
1054	    {
1055	      "verse_id": "5.57.51",
1056	      "sarga": 57,
1057	      "verse": "51",
1058	      "ambiguous_marker": false,
1059	      "sanskrit_iast": "darśanaṃ cāpi laṅkāyāḥ sītāyā rāvaṇasya ca । tasthuḥ prāñjalayaḥ sarve hanūmad vadanonmukhāḥ ॥51॥",
1060	      "leonov_ru": "И о том, как [Хануман] повидал Ланку, Ситу и Равану, Встали, смиренно сложив ладони, все, лицами обратившись к Хануману.",
